package configuration

import (
	"errors"
	"fmt"
	"strconv"
)

// Source resolves a configuration key to a raw value.
type Source func(key string) (value string, found bool)

// Config holds the application configuration values.
type Config struct {
	Port  int
	Name  string
	Debug bool
}

// Load reads configuration keys through source and returns a Config.
// Missing keys get defaults. Present-but-invalid values return an error
// whose chain preserves the underlying parse error.
func Load(source Source) (Config, error) {
	var cfg Config
	var errs []error

	// HELIOS_PORT
	if v, ok := source("HELIOS_PORT"); ok {
		port, err := strconv.Atoi(v)
		if err != nil {
			errs = append(errs, fmt.Errorf("HELIOS_PORT: %w", err))
		} else if port < 1 || port > 65535 {
			errs = append(errs, fmt.Errorf("HELIOS_PORT: value %d out of range [1,65535]", port))
		} else {
			cfg.Port = port
		}
	} else {
		cfg.Port = 8080
	}

	// HELIOS_NAME
	if v, ok := source("HELIOS_NAME"); ok {
		if v == "" {
			errs = append(errs, errors.New("HELIOS_NAME: must not be empty"))
		} else {
			cfg.Name = v
		}
	} else {
		cfg.Name = "helios"
	}

	// HELIOS_DEBUG
	if v, ok := source("HELIOS_DEBUG"); ok {
		debug, err := strconv.ParseBool(v)
		if err != nil {
			errs = append(errs, fmt.Errorf("HELIOS_DEBUG: %w", err))
		} else {
			cfg.Debug = debug
		}
	} else {
		cfg.Debug = false
	}

	return cfg, errors.Join(errs...)
}

package main

import (
	"fmt"
	"os"

	"example.helios/configuration"
)

func main() {
	cfg, err := configuration.Load(func(k string) (string, bool) { return os.LookupEnv(k) })
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("port=%d name=%s debug=%t\n", cfg.Port, cfg.Name, cfg.Debug)
}

package configuration

import (
	"errors"
	"strconv"
	"testing"
)

func strSource(m map[string]string) Source {
	return func(key string) (string, bool) {
		v, ok := m[key]
		return v, ok
	}
}

func TestLoadDefaults(t *testing.T) {
	cfg, err := Load(strSource(nil))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want helios", cfg.Name)
	}
	if cfg.Debug != false {
		t.Errorf("Debug = %t, want false", cfg.Debug)
	}
}

func TestLoadAllExplicit(t *testing.T) {
	cfg, err := Load(strSource(map[string]string{
		"HELIOS_PORT":  "9090",
		"HELIOS_NAME":  "myapp",
		"HELIOS_DEBUG": "true",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 9090 {
		t.Errorf("Port = %d, want 9090", cfg.Port)
	}
	if cfg.Name != "myapp" {
		t.Errorf("Name = %q, want myapp", cfg.Name)
	}
	if cfg.Debug != true {
		t.Errorf("Debug = %t, want true", cfg.Debug)
	}
}

func TestLoadBadPort(t *testing.T) {
	_, err := Load(strSource(map[string]string{"HELIOS_PORT": "notanumber"}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if !errors.Is(err, strconv.ErrSyntax) {
		t.Errorf("expected ErrSyntax in error chain, got %v", err)
	}
}

func TestLoadPortOutOfRange(t *testing.T) {
	_, err := Load(strSource(map[string]string{"HELIOS_PORT": "0"}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	_, err = Load(strSource(map[string]string{"HELIOS_PORT": "65536"}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
}

func TestLoadEmptyName(t *testing.T) {
	_, err := Load(strSource(map[string]string{"HELIOS_NAME": ""}))
	if err == nil {
		t.Fatal("expected error for empty name, got nil")
	}
}

func TestLoadBadDebug(t *testing.T) {
	_, err := Load(strSource(map[string]string{"HELIOS_DEBUG": "maybe"}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if !errors.Is(err, strconv.ErrSyntax) {
		t.Errorf("expected ErrSyntax in error chain, got %v", err)
	}
}

func TestLoadMultipleErrors(t *testing.T) {
	_, err := Load(strSource(map[string]string{
		"HELIOS_PORT":  "xyz",
		"HELIOS_NAME":  "",
		"HELIOS_DEBUG": "bad",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	// Should contain errors for all three keys.
	var count int
	for next := err; next != nil; next = errors.Unwrap(next) {
		count++
	}
	if count < 3 {
		t.Errorf("expected at least 3 wrapped errors, got %d", count)
	}
}

func TestLoadPartialOverride(t *testing.T) {
	cfg, err := Load(strSource(map[string]string{
		"HELIOS_NAME": "partial",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080 (default)", cfg.Port)
	}
	if cfg.Name != "partial" {
		t.Errorf("Name = %q, want partial", cfg.Name)
	}
	if cfg.Debug != false {
		t.Errorf("Debug = %t, want false (default)", cfg.Debug)
	}
}

